cat > /private/tmp/nested-message-capture.cjs <<'NESTED_CAPTURE_EOF'
const fs = require('fs');
const {chromium} = require('/Users/rgb/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async () => {
 const browser = await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});
 try {
  const context = await browser.newContext();
  const page = await context.newPage();
  const failures=[];
  page.on('pageerror',e=>failures.push(String(e)));
  await page.goto('http://127.0.0.1:18739/dreyeck/nested-actions/message-witness.html');
  const [popup] = await Promise.all([page.waitForEvent('popup'),page.getByRole('button',{name:'Open producer popup'}).click()]);
  popup.on('pageerror',e=>failures.push(String(e)));
  await popup.waitForLoadState();
  await popup.getByRole('button',{name:'Send props.title',exact:true}).click();
  await page.waitForFunction(()=>JSON.parse(document.querySelector('#capture').textContent).events.length === 1);
  await popup.getByRole('button',{name:'Send props.name fallback',exact:true}).click();
  await page.waitForFunction(()=>JSON.parse(document.querySelector('#capture').textContent).events.length === 2);
  const capture = JSON.parse(await page.locator('#capture').innerText());
  if (failures.length) throw Error(failures.join('\n'));
  if (capture.events[0].receivedMessage.title !== 'Payload Title') throw Error('title branch failed');
  if (capture.events[1].receivedMessage.title !== 'Fallback Node') throw Error('name normalization failed');
  for (const event of capture.events) {
   if (!event.reception.sourceIsPopup || !event.reception.distinctFromSenderObject) throw Error('not native opener reception');
   if (event.listeners.some(h=>h.count !== capture.events.indexOf(event)+1)) throw Error('listener count failed');
   if (event.nestedInput.value !== null || event.reportLookupTarget.value !== null) throw Error('gap fabricated');
  }
  fs.writeFileSync('dreyeck/nested-actions/message-witness.json',JSON.stringify(capture,null,2)+'\n');
  await page.screenshot({path:'/private/tmp/nested-message-witness.png',fullPage:true});
  console.log(JSON.stringify({status:'NATIVE-MESSAGE-CAPTURE-PASS',events:capture.events.length,titles:capture.events.map(e=>e.receivedMessage.title),
    listenerCounts:capture.events.map(e=>e.listeners.map(h=>h.count)),native:capture.events.map(e=>e.reception),gap:capture.events[0].nestedInput},null,2));
 } finally { await browser.close(); }
})().catch(e=>{console.error(e);process.exit(1)});

NESTED_CAPTURE_EOF
node /private/tmp/nested-message-capture.cjs > /private/tmp/nested-message-capture.log 2>&1
